import{getFirestore,initializeFirestore,persistentLocalCache,persistentMultipleTabManager,collection,doc,setDoc as _set,updateDoc as _upd,deleteDoc as _del,onSnapshot}from"https://www.gstatic.com/firebasejs/10.12.2/firebase-firestore.js";

import{cfg}from"./firebase-config.js";
const app=initializeApp(cfg),au=getAuth(app);
// Offline support: Firestore keeps a local copy of your data (works across tabs) and syncs when back online.
let db;try{db=initializeFirestore(app,{localCache:persistentLocalCache({tabManager:persistentMultipleTabManager()})})}catch{db=getFirestore(app)}
// Writes hit the local cache instantly and sync later. Never wait for the server's acknowledgement
// (it will not arrive while offline), or dialogs and buttons would hang.
const fire=p=>{p.catch(x=>alert('Could not save: '+x.message))};
const addDoc=(c,d)=>{const r=doc(c);fire(_set(r,d));return Promise.resolve(r)};
const setDoc=(...a)=>{fire(_set(...a));return Promise.resolve()};
const updateDoc=(...a)=>{fire(_upd(...a));return Promise.resolve()};
