 if(tab==='set'){const[cs,ce]=range(j,0);v=`<div class="card"><h3>Pay settings</h3><div class="item row"><span class="mut">Pay per hour</span><b>${m$(j.rate)}</b></div><div class="item row"><span class="mut">Pay period</span><b>${j.period}</b></div><div class="item row"><span class="mut">Periods start on</span><b>${fd(+pd(j.start))}</b></div><div class="item row"><span class="mut">Payday</span><b>${payLabel(j)}</b></div><div class="item row"><span class="mut">Current period</span><b>${fd(+cs)} - ${fd(prevDay(+ce))}</b></div><button class="pri" style="margin-top:12px" data-a="ej">Edit job and pay settings</button></div><div class="card"><h3>Manage</h3><div class="row"><button data-a="csv">Export timesheet (CSV)</button><button class="stop" data-a="dj">Delete job</button></div></div>`}
