// ---------- clock in/out, summary, hold-to-clock ----------
async function toggleClock(id){const c=OPEN();if(c&&c.job===id)return clockOut(c);if(!c)await addDoc(col('entries'),{job:id,start:Date.now(),end:null,note:''});else alert('Clock out of your other job first.')}
async function clockOut(c){const end=Date.now(),j=jobs.find(x=>x.id===c.job),brk=brkFor(j,c.start,end);await updateDoc(dc('entries',c.id),{end,brk});if(j)summary(c,end,j,brk)}
function summary(c,end,j,brk){brk=brk||0;const h=Math.max(0,(end-c.start)/H-brk/60),g=h*j.rate,nt=net(j,g),t=tx(j),w=T();w.setDate(w.getDate()-((w.getDay()+6)%7));
 const wk=sumH(E.filter(x=>x.id!==c.id&&x.start>=w&&jobs.some(y=>y.id===x.job)))+(c.start>=w?h:0),d=$('#dlg');
 d._fn=null;d.innerHTML=`<h3>Shift complete</h3><p class="mut" style="margin:-6px 0 12px">${esc(j.name)} · ${ft(c.start)} - ${ft(end)}</p><div class="item row"><span class="mut">Hours worked</span><b>${fh(h)}</b></div>${brk?`<div class="item row"><span class="mut">Unpaid break</span><b>-${brk} min</b></div>`:''}<div class="item row"><span class="mut">Gross pay</span><b>${m$(g)}</b></div>${t?`<div class="item row"><span class="mut">Tax (${t}%)</span><b>-${m$(g-nt)}</b></div>`:''}<div class="item row"><span>After-tax pay</span><b class="tk">${m$(nt)}</b></div><p class="mut">Week so far: ${fh(wk)}</p><label>Tips / bonus (optional)</label><input id="st" type="number" inputmode="decimal" step="0.01" min="0" placeholder="0.00"><button class="pri big" data-a="stp" data-i="${c.id}">Done</button>`;if(!d.open)d.showModal()}
// Press and hold the ring for ~0.9s to clock in or out (prevents accidental taps).
let hold=null;
function holdEnd(){if(hold){clearTimeout(hold.t);hold.b.classList.remove('holding');hold=null}}
function holdStart(b){holdEnd();b.classList.add('holding');hold={b,t:setTimeout(()=>{const id=b.dataset.hold;hold=null;b.classList.remove('holding');try{navigator.vibrate&&navigator.vibrate(40)}catch{}toggleClock(id).catch(x=>alert(x.message))},900)}}
document.addEventListener('pointerdown',e=>{const b=e.target.closest&&e.target.closest('[data-hold]');if(b)holdStart(b)});
['pointerup','pointercancel'].forEach(t=>addEventListener(t,holdEnd));
document.addEventListener('contextmenu',e=>{if(e.target.closest&&e.target.closest('[data-hold]'))e.preventDefault()});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.repeat&&e.target.closest&&e.target.closest('[data-hold]')){e.preventDefault();holdStart(e.target.closest('[data-hold]'))}});
document.addEventListener('keyup',e=>{if(e.key==='Enter'||e.key===' ')holdEnd()});

