// ---------- reminders + install ----------
const lsGet=k=>{try{return localStorage.getItem(k)}catch{return null}},lsSet=k=>{try{localStorage.setItem(k,'1')}catch{}};
const notify=(t,b)=>{const o={body:b,icon:'icon-192.png',tag:t+b};if(navigator.serviceWorker)navigator.serviceWorker.ready.then(r=>r.showNotification(t,o)).catch(()=>{try{new Notification(t,o)}catch{}});else try{new Notification(t,o)}catch{}};
const bell=()=>{const b=TB.bell;if(!('Notification' in window)){b.hidden=true;return}b.textContent=window.Notification.permission==='granted'&&lsGet('rem')?'🔔 Reminders on':'🔔 Enable reminders'};
TB.bell.onclick=async()=>{if(!('Notification' in window))return;if(Notification.permission==='default')await Notification.requestPermission();if(Notification.permission==='granted'){lsGet('rem')?localStorage.removeItem('rem'):lsSet('rem')}else alert('Notifications are blocked. Allow them in your browser settings.');bell()};bell();
function remind(){if(!uid||window.Notification?.permission!=='granted'||!lsGet('rem'))return;const n=new Date(),k=ymd(n),nm=n.getHours()*60+n.getMinutes(),once=(id,t,b)=>{if(!lsGet(id)){lsSet(id);notify(t,b)}};
 for(const x of S){const j=jobs.find(j=>j.id===x.job);if(!j||x.date!==k)continue;const d=tm(x.start)-nm;if(d>0&&d<=15)once('n1'+x.id+k,'Shift starting soon',`${j.name} starts at ${x.start}`)}
 const a=OPEN(),j=a&&jobs.find(j=>j.id===a.job);if(j){const sh=S.find(x=>x.job===a.job&&ets(x)>a.start&&Date.now()-ets(x)>=9e5&&Date.now()-ets(x)<864e5);if(sh)once('n2'+a.id,'Forgot to clock out?',`Your ${j.name} shift ended at ${sh.end} and you are still clocked in.`);else if(hr(a)>=12)once('n3'+a.id,'Still clocked in',`You have been clocked in at ${j.name} for ${fh(hr(a))}.`)}}
setInterval(remind,30000);setTimeout(remind,4000);
