// swipe left / right on the earnings details page to change week / month / year
let sx0=0,sy0=0,st0=0;
document.addEventListener('touchstart',e=>{const t=e.touches[0];sx0=t.clientX;sy0=t.clientY;st0=Date.now()},{passive:true});
document.addEventListener('touchend',e=>{if(view!=='wkdet'||$('#dlg').open)return;const t=e.changedTouches[0],dx=t.clientX-sx0,dy=t.clientY-sy0;if(Math.abs(dx)<70||Math.abs(dy)>45||Math.abs(dx)<Math.abs(dy)*2||Date.now()-st0>700)return;if(e.target.closest&&e.target.closest('.tabs,.chips,dialog'))return;if(dx>0)wsel--;else{if(wsel>=0)return;wsel++}render();scrollTo(0,0)},{passive:true});
